import random
import string
from typing import List

# Data type: HTTP header field-value (RFC 9110)
# Constraints used by stubs:
# - Arbitrary text excluding CR (\r) and LF (\n)
# - Prefer non-empty values
# - Often used for: Content-Type, Authorization value suffix, MIME types, URL (header-safe), etc.
# Our strategy:
# - Produce seeded, varied, CR/LF-free byte sequences
# - Include a mix of ascii tokens, spaces, separators, UTF-8, and long/short lengths
# - Sometimes generate specific interesting patterns (MIME types, Bearer tokens, URLs, comma lists)
# - Upper size bound: 4096 bytes

SAFE_SEPARATORS = " ;,:/=+*?&_().-\"'<>@[]{}#|!$%^~`"
ASCII_VISIBLE = ''.join(ch for ch in (chr(i) for i in range(32, 127)) if ch not in "\r\n")
UNICODE_SAMPLES = [
    "é", "✓", "—", "α", "β", "漢字", "🙂", "𝛑", "€", "¡", "¿", "ø", "ğ", "ş", "ż",
]

MIME_TYPES = [
    "application/json", "text/plain; charset=utf-8", "text/html; charset=UTF-8",
    "application/octet-stream", "application/xml", "image/png", "image/jpeg",
    "multipart/form-data; boundary=------------------------fuzzboundary",
]

AUTH_SCHEMES = [
    lambda rng: "Bearer " + random_token(rng, rng.randint(8, 64)),
    lambda rng: "Basic " + random_token(rng, rng.randint(8, 32)),
    lambda rng: "Digest username=\"user\", realm=\"r\", nonce=\"" + random_token(rng, 16) + "\"",
]

URL_TEMPLATES = [
    lambda rng: "/" + random_token(rng, rng.randint(1, 40)),
    lambda rng: "/path/" + random_token(rng, rng.randint(3, 12)) + "?q=" + random_token(rng, rng.randint(3, 12)),
    lambda rng: "https://" + random_token(rng, rng.randint(3, 10)) + ".example.com/" + random_token(rng, rng.randint(3, 10)),
]

COMMA_LIST_SETS = [
    ["gzip", "deflate", "br"],
    ["keep-alive", "close"],
    ["en-US", "en;q=0.8", "fr;q=0.7"],
]


def random_token(rng: random.Random, length: int) -> str:
    alphabet = string.ascii_letters + string.digits + SAFE_SEPARATORS
    return ''.join(rng.choice(alphabet) for _ in range(length))


def make_value_variant(rng: random.Random) -> str:
    choice = rng.randint(0, 9)
    if choice == 0:
        return rng.choice(MIME_TYPES)
    if choice == 1:
        return rng.choice(AUTH_SCHEMES)(rng)
    if choice == 2:
        return rng.choice(URL_TEMPLATES)(rng)
    if choice == 3:
        items = rng.choice(COMMA_LIST_SETS)
        # Possibly shuffle and join with comma-space
        vals = items[:]
        rng.shuffle(vals)
        return ', '.join(vals)
    if choice == 4:
        # Quoted string with escaped quotes
        inner = random_token(rng, rng.randint(3, 40)).replace('"', '\\"')
        return f'"{inner}"'
    if choice == 5:
        # Long ASCII visible string
        return ''.join(rng.choice(ASCII_VISIBLE) for _ in range(rng.randint(20, 200)))
    if choice == 6:
        # Repeated key=value; pairs separated by semicolons
        parts = []
        for _ in range(rng.randint(2, 6)):
            k = ''.join(rng.choice(string.ascii_letters + string.digits + "-_") for _ in range(rng.randint(3, 10)))
            v = random_token(rng, rng.randint(1, 12)).strip()
            parts.append(f"{k}={v}")
        return '; '.join(parts)
    if choice == 7:
        # UTF-8 heavy
        parts: List[str] = []
        for _ in range(rng.randint(3, 15)):
            if rng.random() < 0.5:
                parts.append(rng.choice(UNICODE_SAMPLES))
            else:
                parts.append(random_token(rng, rng.randint(1, 6)))
        return ' '.join(parts)
    if choice == 8:
        # Numeric value or range
        a = rng.randint(0, 10**6)
        b = rng.randint(a, a + 10**6)
        if rng.random() < 0.5:
            return str(a)
        else:
            return f"bytes={a}-{b}"
    # Default: short token
    return random_token(rng, rng.randint(1, 32))


def sanitize_no_crlf(s: str) -> str:
    return s.replace('\r', '').replace('\n', '')


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose total length target under 4096
    target_len = rng.randint(1, 1024)
    parts: List[str] = []
    while len(''.join(parts)) < target_len:
        part = make_value_variant(rng)
        part = sanitize_no_crlf(part)
        if not part:
            part = 'v'
        parts.append(part)
        # Occasionally add separators to emulate combined header values
        if rng.random() < 0.3:
            parts.append(', ' if rng.random() < 0.5 else '; ')
        elif rng.random() < 0.2:
            parts.append(' ')
    val = ''.join(parts)
    # Trim to max 4096 bytes
    val_bytes = val.encode('utf-8')[:4096]
    if not val_bytes:
        val_bytes = b'v'
    return val_bytes
